--
-- Table structure for table `dimproduct`
--

DROP TABLE IF EXISTS `dimproduct`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dimproduct` (
  `ProductID` int NOT NULL AUTO_INCREMENT,
  `ProductCode` varchar(12) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ProductName` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `SubCategory` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Brand` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Supplier` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `CostPrice` decimal(10,2) NOT NULL,
  `SellingPrice` decimal(10,2) NOT NULL,
  `IsActive` tinyint(1) NOT NULL DEFAULT '1',
  `CreatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ProductID`),
  UNIQUE KEY `ProductCode` (`ProductCode`),
  CONSTRAINT `chk_costprice` CHECK ((`CostPrice` > 0)),
  CONSTRAINT `chk_sellingprice` CHECK ((`SellingPrice` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=2001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

