DROP TABLE IF EXISTS `dimstore`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dimstore` (
  `StoreID` int NOT NULL AUTO_INCREMENT,
  `StoreCode` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `StoreName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `StoreType` enum('Mall','Standalone','Supermarket','Outlet') COLLATE utf8mb4_unicode_ci NOT NULL,
  `Region` enum('North','South','East','West') COLLATE utf8mb4_unicode_ci NOT NULL,
  `StoreSize` enum('Small','Medium','Large') COLLATE utf8mb4_unicode_ci NOT NULL,
  `City` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `State` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Country` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `OpeningDate` date NOT NULL,
  `CreatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`StoreID`),
  UNIQUE KEY `StoreCode` (`StoreCode`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

