--
-- Table structure for table `factsales`
--

DROP TABLE IF EXISTS `factsales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `factsales` (
  `SaleID` bigint NOT NULL AUTO_INCREMENT,
  `CustomerID` int NOT NULL,
  `ProductID` int NOT NULL,
  `StoreID` int NOT NULL,
  `DateID` int NOT NULL,
  `Quantity` smallint unsigned NOT NULL,
  `UnitPrice` decimal(10,2) NOT NULL,
  `DiscountAmount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `SalesAmount` decimal(12,2) NOT NULL,
  `CostAmount` decimal(12,2) NOT NULL,
  `ProfitAmount` decimal(12,2) NOT NULL,
  `PaymentMethod` enum('Cash','Credit Card','Debit Card','UPI','Net Banking','Wallet') COLLATE utf8mb4_unicode_ci NOT NULL,
  `CreatedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`SaleID`),
  KEY `idx_sales_customer` (`CustomerID`),
  KEY `idx_sales_product` (`ProductID`),
  KEY `idx_sales_store` (`StoreID`),
  KEY `idx_sales_date` (`DateID`),
  KEY `idx_sales_date_store` (`DateID`,`StoreID`),
  KEY `idx_sales_product_date` (`ProductID`,`DateID`),
  CONSTRAINT `FK_Sales_Customer` FOREIGN KEY (`CustomerID`) REFERENCES `dimcustomer` (`CustomerID`),
  CONSTRAINT `FK_Sales_Date` FOREIGN KEY (`DateID`) REFERENCES `dimdate` (`DateID`),
  CONSTRAINT `FK_Sales_Product` FOREIGN KEY (`ProductID`) REFERENCES `dimproduct` (`ProductID`),
  CONSTRAINT `FK_Sales_Store` FOREIGN KEY (`StoreID`) REFERENCES `dimstore` (`StoreID`),
  CONSTRAINT `chk_costamount` CHECK ((`CostAmount` >= 0)),
  CONSTRAINT `chk_discount` CHECK ((`DiscountAmount` >= 0)),
  CONSTRAINT `chk_quantity` CHECK ((`Quantity` > 0)),
  CONSTRAINT `chk_salesamount` CHECK ((`SalesAmount` >= 0)),
  CONSTRAINT `chk_unitprice` CHECK ((`UnitPrice` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=100001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

